import{_ as s,a0 as i,w as a,s as r,I as n,x as e,a1 as p,A as o,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何从 Ubuntu 22.04 LTS 升级到 22.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何从 Ubuntu 22.04 LTS 升级到 22.10 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从 Ubuntu 22.04 LTS 升级到 22.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从 Ubuntu 22.04 LTS 升级到 22.10 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic)","title":"如何从 Ubuntu 22.04 LTS 升级到 22.10","tag":"202211","desc":""},"relativePath":"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic).md","filePath":"[post].md"}'),d={name:"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic).md"};function b(m,t,g,h,w,f){const u=i("Link");return a(),r("div",null,[t[24]||(t[24]=n("h1",{id:"如何从-ubuntu-22-04-lts-升级到-22-10",tabindex:"-1"},[e("如何从 Ubuntu 22.04 LTS 升级到 22.10 "),n("a",{class:"header-anchor",href:"#如何从-ubuntu-22-04-lts-升级到-22-10","aria-label":"Permalink to “如何从 Ubuntu 22.04 LTS 升级到 22.10”"},"​")],-1)),t[25]||(t[25]=n("blockquote",null,[n("p",null,"这里是如何将你当前的 Ubuntu 22.04 LTS Jammy Jellyfish 升级到 Ubuntu 22.10 Kinetic Kudu 的步骤。")],-1)),n("p",null,[t[1]||(t[1]=e("始终停留在长期支持的发布版本，这是金科玉律。因为，先前的 ",-1)),p(u,{href:"https://www.debugpoint.com/ubuntu-22-04-review/"},{default:o(()=>[...t[0]||(t[0]=[e("Ubuntu 22.04 LTS",-1)])]),_:1}),t[2]||(t[2]=e(" Jammy Jellyfish 将被支持到 2027 年 4 月。这是一段很长的时间。",-1))]),t[26]||(t[26]=n("p",null,"此外，LTS 版本超级稳定。它们很少损坏并变得不稳定。因此，如果你在笔记本电脑/台式机电脑或服务器上安装使用 LTS 版本，保持使用它。",-1)),n("p",null,[t[4]||(t[4]=e("然而，如果你想要最新的内核、GNOME 43 和 Pipewire 之类的最新技术 – 你可能会想完成版本跳级，并升级到 ",-1)),p(u,{href:"https://www.debugpoint.com/ubuntu-22-10/"},{default:o(()=>[...t[3]||(t[3]=[e("Ubuntu 22.10 Kinetic Kudu",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[27]||(t[27]=l(`<p>这里是如何做的方法。</p><h3 id="升级-ubuntu-22-04-lts-到-ubuntu-22-10" tabindex="-1">升级 Ubuntu 22.04 LTS 到 Ubuntu 22.10 <a class="header-anchor" href="#升级-ubuntu-22-04-lts-到-ubuntu-22-10" aria-label="Permalink to “升级 Ubuntu 22.04 LTS 到 Ubuntu 22.10”">​</a></h3><p><strong>注意</strong>：我希望你没有运行去年 10 月份发布的 Ubuntu 21.10 Impish Indri 。因为它已经不被支持。但是鉴于某些原因，你正在运行它，我建议你直接重新安装 22.10 。或者，先升级到 22.04 ，再升级到 22.10 。</p><h4 id="在你升级前" tabindex="-1">在你升级前 <a class="header-anchor" href="#在你升级前" aria-label="Permalink to “在你升级前”">​</a></h4><p>在你升级前，做一些内务整理。这是非常重要的。</p><ul><li>备份你的 <code>/home</code>、/<code>downloads</code> 和其它的文件到 USB 驱动器或任意独立的分区，以防升级失败。</li><li>如果你随着时间的流逝而添加了一些额外的 PPA ，确保将它们记录下来。虽然，在升级过程开始前，升级过程将禁用 PPA 。而在升级完成后，确保手动启用 PPA 。</li><li>记录并禁用所有的 GNOME 扩展。如果开发人员没有按照 GNOME 版本进行更新，那么扩展在升级后将会损坏。</li><li>家中常备一个现场 USB 磁盘。</li></ul><h4 id="升级步骤" tabindex="-1">升级步骤 <a class="header-anchor" href="#升级步骤" aria-label="Permalink to “升级步骤”">​</a></h4><p>打开 “<ruby>软件包和更新<rt>Software &amp; Update</rt></ruby>” 。</p><p>转到 “<ruby>更新<rt>Updates</rt></ruby>” 标签页。</p><p>转到 “<ruby>通知我新的 Ubuntu 版本<rt>Notify me of a new Ubuntu version</rt></ruby>”，选择并将其更改为 “<ruby>任意新的版本<rt>For any new version</rt></ruby>”。</p><p>这将告诉软件包管理器来查找 Ubuntu 22.10 发布版本的详细信息。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Make-sure-to-change-the-option-for-new-Ubuntu-22.10-release.jpg" alt="Make sure to change the option for new Ubuntu 22.10 release"></p><p>打开一个终端，并运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>或者，你也可以打开软件包更新程序。安装所有的准备就绪的软件包。</p><p>在两个命令完成后，打开软件包更新。你将会看到一个升级到 Ubuntu 22.10 的提示（如下图所示）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/New-version-update-prompt-from-the-GUI-method2.jpg" alt="New version update prompt from the GUI method"></p><p>现在，单击 “<ruby>升级<rt>Upgrade</rt></ruby>” 按钮，并按照屏幕上的说明进行操作。升级过程需要一些时间，因此，要耐心等待，直至升级完成。确保在整个升级过程中有稳定的互联网链接。</p><p>如果你尚未获得更新，请等待一、两天后再次尝试。</p><p>如果你没有看到上述提示，手动重新启动一次系统。并再次添加尝试。</p><h4 id="通过终端" tabindex="-1">通过终端 <a class="header-anchor" href="#通过终端" aria-label="Permalink to “通过终端”">​</a></h4><p>在终端中通过 nano 文件编辑器打开下面的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano /etc/update-manager/release-upgrades</span></span></code></pre></div><p>将 <code>Prompt=LTS</code> 更改为 <code>Prompt=normal</code> 。注意：如果你已经如上所述将更新标签页更改为 “<ruby>任意新的版本<rt>For any new version</rt></ruby>” ，那么这个文件应该已经更新了。但是，要验证它一次。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Change-the-release-upgrade-file.jpg" alt="Change the release upgrade file"></p><p>分别按下组合键 <code>CTRL+O</code> 和组合键 <code>CTRL+X</code> 来保存和退出。</p><p>最后，你也可以运行下面的命令来从终端中强制升级过程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo do-release-upgrade -c</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/New-version-update-prompt-from-the-terminal-method.jpg" alt="New version update prompt from the terminal method"></p><p>升级过程需要花费一些时间（最少半个小时，上不封顶），这主要取决于你的互联网连接和硬件。直至等到其完成。在完成后，重新启动并享受 Ubuntu 22.10 Kinetic Kudu.</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Upgrade-is-in-progress.jpg" alt="Upgrade is in progress"></p>`,31)),n("p",null,[t[7]||(t[7]=e("在升级过程进行时，看看我们 ",-1)),p(u,{href:"https://www.debugpoint.com/tag/ubuntu-22-10"},{default:o(()=>[...t[6]||(t[6]=[e("不久前发布的关于 Ubuntu 22.10",-1)])]),_:1}),t[8]||(t[8]=e(" 的精彩文章。",-1))]),t[28]||(t[28]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),p(u,{href:"https://www.debugpoint.com/upgrade-ubuntu-22-04-22-10/"},{default:o(()=>[...t[9]||(t[9]=[e("https://www.debugpoint.com/upgrade-ubuntu-22-04-22-10/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),p(u,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[11]||(t[11]=[e("Arindam",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),p(u,{href:"https://github.com/lkxed"},{default:o(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),p(u,{href:"https://github.com/robsean"},{default:o(()=>[...t[13]||(t[13]=[e("robsean",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),p(u,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),p(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),p(u,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const y=s(d,[["render",b]]);export{U as __pageData,y as default};
